import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"周易尚氏学 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"周易尚氏学 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/057.md","filePath":"zh/classics/shangshi/057.md"}'),h={name:"zh/classics/shangshi/057.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>艮其背。不获其身。行其庭。不见其人。无咎。归藏作狠。狠广韵很之俗宇。说文很不听从也。一曰行难也。艮郑云艮之言很也。是很艮义同。艮止也。震为行。震反故止。杂卦震起也。艮止也。即言正反之义也。旧说以阳在上为止。非其义也。艮为背为身为庭为人。艮其背。静也。三至五互震。故又曰行其庭。行其庭动也。乃因无应与。静则不获身上手足之用。动则不见庭除应予之人。无动作无交际。故亦无咎也。</p><p>彖曰。艮。止也。时止则止。时行则行。动静不失其时。其道光明。艮其止。止其所也。上下敌应。不相与也。是以不获其身。行其庭不见其人。无咎也。</p><p>艮为时。下艮。故曰时止则止。三至五互震。故曰时行则行。止则静。行则动。动静随时。故其道光明。艮为道路。阳在上故光明。六爻无应予。故曰敌应。阴阳相遇为朋为类。若阳遇阳。阴遇阴。则皆为敌。同人九三云。敌刚。以比应皆阳。故曰敌刚。以阳遇阳为敌。中孚六三云。得敌。子夏传云。四与三为敌。而不释其义。荀爽解之曰。三四俱阴。故称敌也。以阴遇阴为敌。此实易义之根本。明乎此则屯二之十年乃字。此三之比之匪人。颐六二之失类。六五之不利涉。大壮初九之征凶。解九四这解而拇。夬初九之往不胜。九四之其行次且。鼎九二之慎所之。震六五之往厉。皆可观象而得其义。否则不知其所谓矣。此易义之所以终古长夜也。然观子夏传之解得敌。似此义韩婴已知之。荀爽能释之。然可以于上列各爻。任其失解。抑有解而采辑者不合其意而不录欤。</p><h3 id="象曰。兼山。艮。君子以思不出其位。" tabindex="-1">象曰。兼山。艮。君子以思不出其位。 <a class="header-anchor" href="#象曰。兼山。艮。君子以思不出其位。" aria-label="Permalink to “象曰。兼山。艮。君子以思不出其位。”">​</a></h3><p>艮为位，艮止故不出。坎为思。得中唯心亨。亦不出。学易之君子法之。</p><p>初六。艮其趾 无咎。利永贞。</p><p>爻例在下称趾。足上不动。故无咎，利永贞者。利于永远贞定也。着初失位无应遇敌。故贵于无为也。趾荀作止，止古文趾字。</p><h3 id="象曰。艮其趾。未失正也。" tabindex="-1">象曰。艮其趾。未失正也。 <a class="header-anchor" href="#象曰。艮其趾。未失正也。" aria-label="Permalink to “象曰。艮其趾。未失正也。”">​</a></h3><p>利永贞。故不失正。</p><p>六二。艮其用腓。 不拯其随。其心不快。</p><p>腓。胫肚也。义详咸卦。腓之用在行。艮其腓。是不行也。拯京房作升。举也。释文作承。曰马云举也。可证马氏王氏本原作承。今作拯者。盖开成以后所定。然升承拯音义并同。艮为手。故曰拯。艮止故不拯。然阴以顺阳为天职。仍须随阳。故曰不拯其随。坎为心为优。既不可动。又须随阳。不能自主。故其心不快。</p><h3 id="象曰。不拯其随。未退听也。" tabindex="-1">象曰。不拯其随。未退听也。 <a class="header-anchor" href="#象曰。不拯其随。未退听也。" aria-label="Permalink to “象曰。不拯其随。未退听也。”">​</a></h3><p>坎马耳。故曰听。听从也。腓之用在动而前进。不拯是不动不前。而退听也。然阳在上。义必随行。是又不能退听也。进退不克自主。故心不快也。</p><p>九三。艮其限。列其夤。厉熏心。</p><p>限。说文阻也。玉篇界也。即脊骨界左右也。故马荀郑虞皆训为要。三居卦中。坎为要。故取象于限。坎为脊为肉。故取明于夤。夤。马虞皆以为夹脊肉。脊骨居中为限。脊肉左右分列。列裂同。墨子明鬼下云。生列兕虎。荀子哀公问云。两骖列两服人厩。注皆作裂。脊肉裂分左右。脊界其中。故曰裂其夤。皆坎象也。艮为火。互坎为心。故厉熏心。自坎肉象失传。后懦皆不知噬嗑三四五三爻之肉象。及．此夤象何属。自艮火象失传。虞翻以艮为阍。读紊为阍。谓古阍作熏字。并云马吉熏灼其心。未闻易道以坎水熏灼人者。岂知艮为火。马氏所诂。正与易合。至荀氏以熏为动。读作动。来知德。又云以三十年之功。始悟熏字之由于伏离。由斯证一象之失传。可使名家易人人异词。真可叹也。艮火坎肉象。皆详焦氏易诂。易林艮之无妄云。。颠覆不制。痛熏我心。是焦亦作熏。</p><h3 id="象曰。艮其限。危熏心也。" tabindex="-1">象曰。艮其限。危熏心也。 <a class="header-anchor" href="#象曰。艮其限。危熏心也。" aria-label="Permalink to “象曰。艮其限。危熏心也。”">​</a></h3><p>厉危也。故曰危熏心。</p><p>六四。艮其身。无咎。</p><p>艮为身。见上彖。虞以坤为身为孕非也。初趾二腓。三要四身。按爻序自下而上。故象释为躬。得位故无咎。</p><h3 id="象曰。艮其身。止诸躬也。" tabindex="-1">象曰。艮其身。止诸躬也。 <a class="header-anchor" href="#象曰。艮其身。止诸躬也。" aria-label="Permalink to “象曰。艮其身。止诸躬也。”">​</a></h3><p>艮为躬。躬即身也。三四居卦之中。故曰要。曰身。并无他义。虞氏谓五动乘四则妊身。以止诸躬为妊身。卦天离象。强命王爻。变成离。惑乱学。莫此为甚。</p><p>六五。艮其辅。言有序。悔亡。</p><p>辅。说文人颊车也。在颊之上。与牙车相对。春秋僖五年。辅车相依。注云。车牙车。疏牙车。牙下骨之名。在颊之下。盖几物人口。皆赖牙车载之。故名曰车。人欲嚼物。或言语。则牙动而上与辅对。故曰辅车相依。辅在上不动。故艮为辅。颐即用以取象。三至五震。震为言。上卦震反。故曰艮其辅。序者次也。言不紊也。三至五震。时而当言则言。四至上。震反。时而不当言。则言止矣。故曰言有序。诗大雅序宾以贤。言宾之位次。与其贤相当。秩然不乱也。言行君子之枢机。时言则言。时止则止。有序如是。故无悔也。虞氏易序作孚。言孚于上也。</p><h3 id="象曰。艮其辅。以中正也。" tabindex="-1">象曰。艮其辅。以中正也。 <a class="header-anchor" href="#象曰。艮其辅。以中正也。" aria-label="Permalink to “象曰。艮其辅。以中正也。”">​</a></h3><p>五中而不正。正字或疑衍。又或作正中。然未济九二传。中以行正也。大壮九二传。大者正也。大谓九二。似亦不拘。</p><p>上九。敦艮吉。</p><p>敦与顿通。顿止也。易凡言敦。皆有止义。待义。义详敦临敦复。敦艮者。顿止于上也。下履重阴。故吉。</p><h3 id="象曰。敦艮之吉。以厚终也。" tabindex="-1">象曰。敦艮之吉。以厚终也。 <a class="header-anchor" href="#象曰。敦艮之吉。以厚终也。" aria-label="Permalink to “象曰。敦艮之吉。以厚终也。”">​</a></h3><p>艮为山。故曰厚。而艮为终。故曰以厚终。唯厚故止也。</p>',30)])])}const f=e(h,[["render",s]]);export{_ as __pageData,f as default};
